from pathlib import Path
import base64
B=Path('/home/user/rebrand')
def img(name,cls=''):
 p=B/name;mime='image/webp' if p.suffix=='.webp' else 'image/svg+xml'
 return f'<img class="{cls}" src="data:{mime};base64,{base64.b64encode(p.read_bytes()).decode()}">'
def foot(n):return f'<footer><span>ПОТОЛКОВО / BRAND & DIGITAL · КОНЦЕПЦИЯ 01</span><span>14.10.2026 · {n:02} / 10</span></footer>'
def top(n,kicker,title,desc=''):
 return f'<div class="kicker">{kicker}</div><h1>{title}</h1>'+(f'<p class="intro">{desc}</p>' if desc else '')
css='''@page{size:320mm 180mm;margin:0}*{box-sizing:border-box}body{margin:0;background:#ecefe7;color:#173c36;font-family:Arial,sans-serif}.slide{position:relative;width:320mm;height:180mm;padding:12mm 16mm 14mm;break-after:page;overflow:hidden;background:#f6f5ef}.slide:last-child{break-after:auto}.dark{background:#173c36;color:#f6f5ef}.kicker{font-size:9pt;letter-spacing:1.8px;text-transform:uppercase;margin-bottom:5mm;font-weight:600}h1,h2,h3,p{margin:0}h1{font-size:31pt;letter-spacing:-1.6px;line-height:1.07;font-weight:500}h2{font-size:25pt;line-height:1.12;letter-spacing:-1px;font-weight:500}h3{font-size:17pt;font-weight:500;line-height:1.2}p{font-size:11pt;line-height:1.55}.intro{color:#53675e;margin-top:4mm;font-size:11pt}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9mm;margin-top:9mm}.box{padding:8mm;background:#e7ecdd;border-radius:2mm}.box.white{background:#fff}.box.darkbox{background:#173c36;color:#f6f5ef}.box h3{margin-bottom:6mm}.box p{font-size:11pt;margin-top:4mm}ul{padding-left:5mm;margin:6mm 0 0}li{font-size:11pt;line-height:1.55;margin:3mm 0}.big{font-size:46pt;letter-spacing:-2px;line-height:1.05}.cover{display:grid;grid-template-columns:1fr 1fr;gap:12mm;height:100%;align-items:center}.cover .hero{width:100%;height:145mm;object-fit:cover;border-radius:2mm}.cover .big{margin:12mm 0 8mm}.lime{color:#d7ed89}.cover p{color:#d1ddc8;font-size:12pt}.chip{display:inline-block;border:1px solid #6d897a;padding:3mm 4mm;border-radius:1mm;font-size:8pt;margin:8mm 2mm 0 0}.image-label{font-size:8pt;opacity:.8;margin-top:3mm}.logo{width:117mm;max-height:25mm;object-fit:contain;object-position:left}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:4mm;margin-top:8mm}.swatch{height:40mm;padding:5mm;display:flex;flex-direction:column;justify-content:space-between;font-size:10pt;border:1px solid #dae1d4;border-radius:2mm}.swatch small{font-size:8pt}.typebar{border-top:1px solid #bbc7b6;margin-top:8mm;padding-top:6mm;display:grid;grid-template-columns:1fr 1fr;gap:15mm}.typebar h2{font-size:28pt}.typebar p{font-size:10pt}.screenrow{display:grid;grid-template-columns:217mm 1fr;gap:10mm;margin-top:7mm;align-items:start}.screenrow>img{width:217mm;height:125mm;object-fit:contain;object-position:top left;border:1px solid #d7dfcf;border-radius:2mm}.slide:nth-child(6) .screenrow>img,.slide:nth-child(7) .screenrow>img{height:114mm}.sidenotes h3{font-size:17pt;margin-top:2mm}.sidenotes p{font-size:10pt;color:#53675e;margin-top:4mm}.sidenotes .n{font-size:8pt;margin-top:7mm;color:#617452}.mobile{display:grid;grid-template-columns:62mm 62mm 1fr;gap:14mm;margin-top:8mm;align-items:start}.mobile img{width:62mm;height:124mm;object-fit:contain;object-position:top left;border:1px solid #cad5bf;border-radius:3mm}.mobile .copy{padding-left:6mm}.mobile .copy h2{margin:8mm 0}.mobile .copy p{font-size:11pt;margin-top:6mm;color:#53675e}.two-screens{display:grid;grid-template-columns:1fr 1fr;gap:9mm;margin-top:8mm}.two-screens img{width:100%;height:102mm;object-fit:contain;object-position:top left;border-radius:2mm}.two-screens h3{font-size:14pt;margin-bottom:4mm}.two-screens p{font-size:9pt;margin-top:4mm;color:#53675e}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:7mm;margin-top:10mm}.step{border-top:1px solid #758f7d;padding-top:6mm}.step span{font-size:9pt;color:#d7ed89}.step h2{font-size:24pt;margin:8mm 0 5mm}.step p{font-size:11pt;color:#c0d0c1}.callout{margin-top:8mm;background:#d7ed89;color:#173c36;padding:7mm;border-radius:2mm;font-size:13pt;line-height:1.4}footer{position:absolute;left:16mm;right:16mm;bottom:5mm;border-top:1px solid #becaba;padding-top:3mm;display:flex;justify-content:space-between;font-size:7pt;letter-spacing:.03em}.dark footer{border-color:#527263;color:#c3d2c3}.note{font-size:8pt!important;color:#617452}.portraitless{background:#e5ebda;padding:9mm;border-radius:2mm;margin-top:8mm;display:grid;grid-template-columns:1fr 1fr;gap:12mm}.portraitless p{font-size:11pt}.strongline{font-size:26pt;line-height:1.12;letter-spacing:-.8px}.tagline{margin-top:5mm;font-size:16pt}.symbolbox{width:12mm;height:12mm;display:inline-flex;border:2px solid #173c36;align-items:center;justify-content:center;font-size:22pt;margin-right:4mm}.smallcaps{font-size:8pt;letter-spacing:1px;color:#617452}@media screen{body{padding:20px}.slide{margin:0 auto 25px;box-shadow:0 10px 40px #10251b15}}'''
pages=[]
pages.append('<section class="slide dark"><div class="cover"><div><div class="kicker">ПОТОЛКОВО / НОВАЯ ГЛАВА</div><div class="big">Потолок и свет,<br>продуманные<br><span class="lime">вместе.</span></div><p>От личного сайта мастера —<br>к компании, которая может расти.</p><span class="chip">СРЕДНИЙ+</span><span class="chip">КОМАНДА И ПАРТНЁРЫ</span><p class="image-label">Направление «Спокойная архитектура»<br>Предложение к утверждению, не готовый бренд-релиз.</p></div><div>'+img('assets/hero.webp','hero')+'<div class="image-label">AI-визуализация. Не объект компании.</div></div></div>'+foot(1)+'</section>')
pages.append('<section class="slide">'+top(2,'01 / Позиционирование','Не просто «я» → «мы».<br>Новая модель доверия.')+'<div class="grid"><div class="box white"><div class="smallcaps">ОТ ЧЕГО УХОДИМ</div><h2 style="margin-top:5mm">Всё держится<br>на одном мастере.</h2><ul><li>Личное выполнение каждого заказа</li><li>Портрет — главный аргумент hero</li><li>Заявки и контроль только у основателя</li></ul></div><div class="box darkbox"><div class="smallcaps" style="color:#c6d9b0">К ЧЕМУ ПРИХОДИМ</div><h2 style="margin-top:5mm">Компания организует<br>результат.</h2><ul><li>Подходящие исполнители под объект</li><li>Решения, состав, условия, доказательства</li><li>Ответственный, передача, приёмка, сервис</li></ul></div></div><div class="portraitless"><div class="strongline">Основатель остаётся.<br>Но перестаёт быть<br>единственным продуктом.</div><p>Не изображаем большой штат. Честно показываем мастеров и партнёрские бригады. Слово «компания» не заменяет реальную договорную сторону.</p></div>'+foot(2)+'</section>')
pages.append('<section class="slide">'+top(3,'02 / Фирменное направление','Спокойная архитектура.')+'<div style="margin-top:8mm">'+img('assets/POTOLKOVO-logo-concept.svg','logo')+'</div><div class="swatches"><div class="swatch" style="background:#173c36;color:white"><b>Глубокий зелёный</b><small>#173C36 · текст / действие</small></div><div class="swatch" style="background:#f6f5ef"><b>Тёплый светлый</b><small>#F6F5EF · фон</small></div><div class="swatch" style="background:#d7ed89"><b>Световой акцент</b><small>#D7ED89 · акцент на тёмном</small></div><div class="swatch" style="background:#c5a56c"><b>Тёплый металл</b><small>#C5A56C · деталь</small></div></div><div class="typebar"><div><h2>Пространство.<br>Точность. Спокойствие.</h2></div><div><p>Архитектурный знак, крупная кириллица, тёплая фотография и немного цвета. Без визуального шума, псевдопремиума и рекламных наклеек.</p><p class="note" style="margin-top:4mm">Знак и шрифт концептуальные. Нужны финализация, лицензия и проверка обозначения; SVG пока не печатный мастер.</p></div></div>'+foot(3)+'</section>')
pages.append('<section class="slide">'+top(4,'03 / Главная · desktop','Результат занимает первый экран.')+'<div class="screenrow">'+img('screens/home-desktop.webp')+'<div class="sidenotes"><div class="n">01 / ПРОДУКТ</div><h3>Потолок + свет</h3><p>Компания видна сразу. Основатель не конкурирует с результатом.</p><div class="n">02 / ДЕЙСТВИЕ</div><h3>Подобрать решение</h3><p>Один главный CTA, не три одинаковые кнопки.</p><div class="n">03 / ЧЕСТНОСТЬ</div><p>Визуализация подписана. Нет выдуманных кейсов и чисел.</p></div></div>'+foot(4)+'</section>')
pages.append('<section class="slide">'+top(5,'04 / Mobile','Не уменьшенный desktop. Свой ритм.')+'<div class="mobile">'+img('screens/home-mobile-first.webp')+img('screens/selection-mobile.webp')+'<div class="copy"><h2>Понятный вход.<br>Крупное действие.<br>Нужный маршрут.</h2><p>На мобильном сначала смысл и кнопка, затем интерьер. Подбор открывается на весь экран.</p><p>Покупатель оборудования не обязан проходить вопросы о потолке. Сложный проект не получает выдуманную смету.</p><p class="note">Локально проверены ширины 320–1440 px и четыре сценария. Реальные устройства и production-интеграция — следующий этап.</p></div></div>'+foot(5)+'</section>')
pages.append('<section class="slide">'+top(6,'05 / Умный свет','Не бейдж SMART.<br>Понятная задача клиента.')+'<div class="screenrow" style="margin-top:5mm">'+img('screens/smart-desktop.webp')+'<div class="sidenotes"><h3>Сценарий → управление → комплект</h3><p>EKS — поставщик компонентов. ПОТОЛКОВО — компания, организующая решение.</p><div class="n">ГРАНИЦА ОБЕЩАНИЯ</div><p>Алиса и приложение — пожелание до проверки конкретной связки устройств.</p><p class="note">Переключатель «День / Вечер / Кино» меняет только визуализацию. Это не тест светотехники.</p></div></div>'+foot(6)+'</section>')
pages.append('<section class="slide">'+top(7,'06 / Структура предложения','Начинаем с потребности,<br>а не с товарного каталога.')+'<div class="screenrow" style="margin-top:5mm">'+img('screens/home-solutions.webp')+'<div class="sidenotes"><h3>Три направления</h3><p>Потолок.<br>Потолок и свет.<br>Оборудование.</p><div class="n">ПРОЦЕСС КОМПАНИИ</div><p>Обсудить → уточнить → согласовать → выполнить и принять.</p><p class="note">Фото карточек взяты из текущего сайта. Перед запуском подтверждаем права и контекст.</p></div></div>'+foot(7)+'</section>')
pages.append('<section class="slide">'+top(8,'07 / Подбор и итог','Один контекст от выбора до заявки.')+'<div class="two-screens"><div><h3>Задача клиента — первым шагом</h3>'+img('screens/selection-desktop.webp')+'<p>Четыре интента. Видимый «Назад», явное закрытие, без принудительного smart-апселла.</p></div><div><h3>Состав прежде уверенной суммы</h3>'+img('screens/result-desktop.webp')+'<p>Прототип показывает конфигурацию. Цена и отправка появятся после подключения проверенных контрактов v6.</p></div></div>'+foot(8)+'</section>')
pages.append('<section class="slide">'+top(9,'08 / Люди и доказательства','Мастера — часть компании.<br>Кейсы — доказательство, не декорация.')+'<div class="grid" style="margin-top:7mm"><div class="box"><h2>Основатель и команда</h2><p>Владимир — в истории компании. Рядом — фактическая модель работы и назначение ответственного.</p><ul><li>Без фиктивных сотрудников</li><li>Без обещания личного монтажа всех заказов</li><li>Без подмены партнёров штатными бригадами</li></ul></div><div class="box white"><h2>Проекты с содержанием</h2><p>Что было нужно клиенту, как решена задача, какие материалы и работы, что вошло в бюджет.</p><ul><li>Только подтверждённые факты</li><li>Согласованные права на фотографии</li><li>Историческая цена не равна текущей смете</li></ul></div></div><div class="callout">Рост требует не только нового сайта: нужны назначение заявок, передача заказа, стандарт монтажа и маршрут рекламаций.</div>'+foot(9)+'</section>')
pages.append('<section class="slide dark">'+top(10,'09 / Порядок внедрения','Бренд — сейчас.<br>Smart-продажи — по готовности.')+'<div class="steps"><div class="step"><span>01 / УТВЕРДИТЬ</span><h2>Направление<br>и ответственность</h2><p>Сообщение, стиль, место основателя. Договорная сторона и модель партнёров.</p></div><div class="step"><span>02 / ВНЕДРИТЬ</span><h2>Цельный сайт<br>компании</h2><p>Главная, услуги, формы, итоги и уведомления. Старые URL и работающие механизмы сохраняем.</p></div><div class="step"><span>03 / РАСШИРИТЬ</span><h2>Проверенные<br>решения света</h2><p>Данные EKS, BOM, цена, документы и стенд. Не тормозим весь ребрендинг ожиданием одного контроллера.</p></div></div><div class="callout">Сейчас нужно согласовать: образ компании, главный слоган и визуальное направление. Затем — финальные макеты и ограниченные PR, не переписывание сайта с нуля.</div><p style="font-size:9pt;color:#bdd0bd;margin-top:6mm">Передано: интерактивный прототип + ТЗ v7 + 18 новых R7 и уточнения к 36 F6. Production-код не изменён.</p>'+foot(10)+'</section>')
(B/'POTOLKOVO-VISUAL-CONCEPT-V7.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>ПОТОЛКОВО — визуальная концепция</title><style>'+css+'</style><body>'+''.join(pages)+'</body></html>')
